#!/usr/bin/env python3
# =============================================================================
# sign_bundle.py - build a key-based CEP-27 Sigstore bundle for one conda
#                  package, the shape `cosign attest-blob --key` produces
#                  (conda-attestation-trust tier, artifact-keeper#4556)
# =============================================================================
# Stdlib plus the openssl CLI. The signing key is generated by the oracle at
# run time in its scratch directory; no key material is ever committed.
#
#   sign_bundle.py --key PRIV.pem --hint-pub PUB.pem --name FILE --sha256 HEX
#                  --out BUNDLE.json [--channel URL]
#
# The in-toto Statement v1 names the package filename and sha256, with the
# CEP-27 predicate type. The DSSE signature covers the DSSE pre-authentication
# encoding (PAE) of the payload, as an ASN.1 DER ECDSA-SHA256 signature from
# `openssl dgst -sha256 -sign`. `verificationMaterial.publicKey.hint` is the
# base64 SHA-256 of the DER SubjectPublicKeyInfo of --hint-pub, which is how a
# key-based bundle names its key. Signing with one key while hinting another
# yields a bundle whose signature does not verify under the hinted key.
# =============================================================================
import argparse
import base64
import hashlib
import json
import subprocess
import sys

PAYLOAD_TYPE = "application/vnd.in-toto+json"


def spki_der(pub_pem):
    return subprocess.run(
        ["openssl", "pkey", "-pubin", "-in", pub_pem, "-outform", "DER"],
        check=True, capture_output=True,
    ).stdout


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--key", required=True)
    ap.add_argument("--hint-pub", required=True)
    ap.add_argument("--name", required=True)
    ap.add_argument("--sha256", required=True)
    ap.add_argument("--out", required=True)
    ap.add_argument("--channel", default="https://conda.example.invalid/dtf")
    a = ap.parse_args()

    statement = {
        "_type": "https://in-toto.io/Statement/v1",
        "subject": [{"name": a.name, "digest": {"sha256": a.sha256}}],
        "predicateType": "https://schemas.conda.org/attestations-publish-1.schema.json",
        "predicate": {"targetChannel": a.channel},
    }
    payload = json.dumps(statement, separators=(",", ":")).encode()
    pae = b"DSSEv1 %d %s %d " % (len(PAYLOAD_TYPE), PAYLOAD_TYPE.encode(), len(payload)) + payload
    sig = subprocess.run(
        ["openssl", "dgst", "-sha256", "-sign", a.key],
        input=pae, check=True, capture_output=True,
    ).stdout
    hint = base64.b64encode(hashlib.sha256(spki_der(a.hint_pub)).digest()).decode()
    bundle = {
        "mediaType": "application/vnd.dev.sigstore.bundle.v0.3+json",
        "verificationMaterial": {"publicKey": {"hint": hint}, "tlogEntries": []},
        "dsseEnvelope": {
            "payload": base64.b64encode(payload).decode(),
            "payloadType": PAYLOAD_TYPE,
            "signatures": [{"sig": base64.b64encode(sig).decode(), "keyid": ""}],
        },
    }
    with open(a.out, "w", encoding="utf-8") as fh:
        json.dump(bundle, fh, separators=(",", ":"))
    return 0


if __name__ == "__main__":
    sys.exit(main())
